// Generated by scripts/sync-draw-blocks.mjs from Draw. Edit the production source, then sync.
// Wire types shared with the Go server; see internal/board/shape.go and
// internal/server/protocol.go.

export type Kind = 'rect' | 'ellipse' | 'line' | 'arrow' | 'pen' | 'text' | 'block' | 'connector'

/** A side of a shape, where a connector leaves or reaches it. */
export type Side = 'left' | 'right' | 'top' | 'bottom'

/**
 * One element on a board. x and y anchor every kind, so moving a shape only
 * changes them: rectangles, ellipses, text and blocks fill w×h from the
 * anchor, lines, arrows and connectors run from the anchor to (x+w, y+h), and
 * pen points are offsets from the anchor.
 */
export interface Shape {
  id: string
  kind: Kind
  x: number
  y: number
  w: number
  h: number
  points?: number[]
  text?: string
  fontSize?: number
  /** For blocks: which building block, a key from blocks.ts such as "agent". */
  block?: string
  /** A block's own labels and platform badges; header and title default to its type's. */
  header?: string
  title?: string
  subtitle?: string
  badges?: string[]
  /**
   * For connectors: the shapes the ends are attached to, and optionally the
   * sides they leave and reach them by (left out, facing sides are picked).
   * An end follows its shape; without one it stays at its point.
   */
  from?: string
  to?: string
  fromSide?: Side
  toSide?: Side
  /** For connectors: an arrowhead where it reaches `to`. */
  head?: boolean
  /** Draws the outline or stroke dashed. Not for text or blocks. */
  dashed?: boolean
  stroke: string
  /** A #rrggbb colour, or "none". For text it is the outline that keeps it readable on top of lines. */
  fill: string
  strokeWidth: number
  /** Stacking order from the server; absent until it acknowledges the add. */
  z?: number
}

/** The area of the board someone sees, in board units. */
export interface Viewport {
  x: number
  y: number
  w: number
  h: number
}

export interface Peer {
  id: string
  name: string
  color: string
  /** Set while they ask everyone to follow them. */
  spotlight?: boolean
  /** The area they last showed. */
  view?: Viewport
}

export interface Patch {
  upsert?: Shape[]
  remove?: string[]
}

/** Board edits. The server acknowledges each one to its sender by seq. */
export type Op =
  | { type: 'add' | 'update'; seq: number; shapes: Shape[] }
  | { type: 'remove'; seq: number; ids: string[] }
  | { type: 'clear'; seq: number }

export type ClientMessage =
  | Op
  | { type: 'cursor'; x?: number; y?: number }
  | ({ type: 'viewport' } & Viewport)
  | { type: 'rename'; name: string }
  | { type: 'spotlight'; on: boolean }

export type ServerMessage =
  | { type: 'welcome'; self: Peer; peers: Peer[]; shapes: Shape[] }
  | ({ type: 'patch'; by: string; seq?: number } & Patch)
  | { type: 'peer'; peer: Peer }
  | { type: 'leave'; id: string }
  | { type: 'cursor'; id: string; x?: number; y?: number }
  | ({ type: 'viewport'; id: string } & Viewport)
  | { type: 'error'; message: string }

/** Shape states by id, where null means the shape does not exist. */
export type Snapshot = Map<string, Shape | null>
